"""Naive, literal reference implementation of the replay contract (testing only)."""
from hashlib import sha256
from math import gcd

PPM = 1000000


def band(counts, eps):
    """counts: dict value->weight. Return (representative, mass)."""
    items = sorted(counts.items())
    best = None  # (weight, -lo, -hi) maximize weight, then min lo, then min hi
    for i, (lo, _) in enumerate(items):
        for j in range(i, len(items)):
            hi = items[j][0]
            if PPM * (hi - lo) > eps * hi:
                continue
            w = sum(wt for v, wt in items[i:j + 1])
            key = (w, -lo, -hi)
            if best is None or key > best[0]:
                num = sum(v * wt for v, wt in items[i:j + 1])
                best = (key, num // w, w)
    return best[1], best[2]


class Ref:
    def __init__(self, topo_spec, settings):
        self.id_to_name = {n['id']: n['name'] for n in topo_spec['nodes']}
        self.name_to_id = {v: k for k, v in self.id_to_name.items()}
        self.extcap = {n['id']: n['external_capacity'] for n in topo_spec['nodes']}
        self.external = set(self.name_to_id[x] for x in topo_spec.get('external_nodes', []))
        self.cap = {}
        for l in topo_spec['links']:
            self.cap[(l['source'], l['target'])] = l['capacity']
            self.cap[(l['target'], l['source'])] = l['capacity']
        for n in self.external:
            self.cap[(-1, n)] = self.extcap[n]
            self.cap[(n, -1)] = self.extcap[n]
        self.flows = sorted(self.cap)
        self.keys = {}
        self.key_to_flow = {}
        for f in self.flows:
            a, b = f
            if a == -1:
                ks = ['low_%s_origination' % self.id_to_name[b]]
            elif b == -1:
                ks = ['low_%s_termination' % self.id_to_name[a]]
            else:
                ks = ['low_%s_egress_to_%s' % (self.id_to_name[a], self.id_to_name[b]),
                      'low_%s_ingress_from_%s' % (self.id_to_name[b], self.id_to_name[a])]
            self.keys[f] = ks
            for k in ks:
                self.key_to_flow[k] = f
        self.all_keys = sorted(self.key_to_flow)
        self.s = settings
        self.counters = {k: None for k in self.all_keys}
        self.demands = {}
        self.paths = None
        self.paths_present = False
        self.snapshots = {}
        self.cache = []  # list of (key, result) ordered oldest..newest

    # ---------------- predictions
    def preds(self):
        out = {}
        for a in self.external:
            out[(-1, a)] = sum(v for (s, d), v in self.demands.items() if s == a)
            out[(a, -1)] = sum(v for (s, d), v in self.demands.items() if d == a)
        if self.paths_present:
            acc = {f: 0 for f in self.flows if f[0] != -1 and f[1] != -1}
            for (s, d), v in self.demands.items():
                if not v:
                    continue
                for entry in self.paths.get((s, d), []):
                    hops, w = entry
                    for h in hops:
                        acc[h] += v * w
            for f in acc:
                out[f] = acc[f] // 1000
        return out

    # ---------------- sampling
    def sample(self, r, f, t, pool):
        if not pool:
            return 0
        txt = '%d:%d:%d:%d:%d' % (self.s['seed'], r, t, f[0], f[1])
        w = int.from_bytes(sha256(txt.encode('ascii')).digest()[:8], 'big')
        return pool[w % len(pool)]

    def pool_of(self, f, preds, predicted):
        p = []
        for k in self.keys[f]:
            if self.counters[k] is not None:
                p.append(self.counters[k])
        if predicted and f in preds:
            p.append(min(preds[f], self.cap[f]))
        return p

    # ---------------- repair
    def repair(self):
        trials = self.s['trials']
        eps = self.s['epsilon']
        predicted = self.paths_present
        preds = self.preds()
        pools = {f: self.pool_of(f, preds, predicted) for f in self.flows}
        fixed = {}
        order = []
        conf = {}
        while len(fixed) < len(self.flows):
            bestf = None
            bestsup = None
            bestcand = None
            for f in self.flows:
                if f in fixed:
                    continue
                counts = {}
                for v in pools[f]:
                    counts[v] = counts.get(v, 0) + trials
                for r in (f[0], f[1]):
                    if r == -1:
                        continue
                    rems = []
                    for t in range(trials):
                        ins = 0
                        outs = 0
                        for g in self.flows:
                            if r not in g:
                                continue
                            v = fixed[g] if g in fixed else self.sample(r, g, t, pools[g])
                            if g[1] == r:
                                ins += v
                            if g[0] == r:
                                outs += v
                        if f[0] == r:
                            rem = ins - outs + (fixed[f] if f in fixed else self.sample(r, f, t, pools[f]))
                        else:
                            rem = outs - ins + self.sample(r, f, t, pools[f])
                        rem = max(0, min(self.cap[f], rem))
                        rems.append(rem)
                    rc = {}
                    for v in rems:
                        rc[v] = rc.get(v, 0) + 1
                    val, mass = band(rc, eps)
                    counts[val] = counts.get(val, 0) + mass
                cand, sup = band(counts, eps)
                if bestsup is None or sup > bestsup:
                    bestsup = sup
                    bestf = f
                    bestcand = cand
            g = gcd(bestsup, trials)
            fixed[bestf] = bestcand
            conf[bestf] = (bestsup // g, trials // g)
            order.append(bestf)
        links = [[f[0], f[1], fixed[f], conf[f][0], conf[f][1]] for f in self.flows]
        counters = {}
        for f in self.flows:
            for k in self.keys[f]:
                counters[k] = {'corrected': fixed[f], 'confidence': list(conf[f])}
        return {'links': tuple(map(tuple, links)),
                'order': tuple(order),
                'counters': tuple(sorted((k, v['corrected'], tuple(v['confidence'])) for k, v in counters.items()))}

    def cache_key(self):
        return (tuple(self.counters[k] for k in self.all_keys),
                tuple(sorted((p, v) for p, v in self.demands.items() if v)),
                self.route_identity(),
                self.s['seed'], self.s['trials'], self.s['epsilon'])

    def route_identity(self):
        if not self.paths_present:
            return None
        out = []
        for (s, d), lst in self.paths.items():
            for hops, w in lst:
                out.append((s, d, hops, w))
        return tuple(sorted(out))

    def do_repair(self, sid):
        key = self.cache_key()
        hit = False
        res = None
        for i, (k, v) in enumerate(self.cache):
            if k == key:
                res = v
                hit = True
                self.cache.append(self.cache.pop(i))
                break
        if res is None:
            res = self.repair()
            if self.s['cache_slots']:
                self.cache.append((key, res))
                while len(self.cache) > self.s['cache_slots']:
                    self.cache.pop(0)
        self.snapshots[sid] = res
        return {'op': 'repair', 'id': sid, 'cache_hit': hit,
                'links': [list(x) for x in res['links']],
                'order': [list(x) for x in res['order']],
                'counters': {k: {'corrected': v, 'confidence': list(c)} for k, v, c in res['counters']}}

    def do_validate(self, sid):
        res = self.snapshots[sid]
        cells = {k: (v, c[0], c[1]) for k, v, c in res['counters']}
        preds = self.preds()
        cn, cd = self.s['cutoff']
        gn, gd = self.s['gamma']
        bias = self.s['bias']
        tau = self.s['tau']
        checked = passed = 0
        failed = []
        for f in self.flows:
            if not self.paths_present and (f[0] != -1 and f[1] != -1):
                continue
            value, num, den = cells[self.keys[f][0]]
            if num * cd < cn * den:
                continue
            n = len(self.keys[f])
            checked += n
            X = value * PPM
            Y = preds[f] * (PPM - bias)
            if PPM * abs(X - Y) <= tau * max(X, Y):
                passed += n
            else:
                failed.extend(self.keys[f])
        failed.sort()
        return {'op': 'validate', 'id': sid, 'checked': checked, 'passed': passed,
                'consistent': None if checked == 0 else (passed * gd >= gn * checked),
                'failed': failed}
